vertexShader:
uniform float uTime; uniform vec3 uWind; attribute float aEnd; attribute float aSpeed; varying float vA;
void main() {
  float s = mod(position.y + uTime * aSpeed, 80.0);                 // distance fallen this cycle (drops start 25 m above the floor, end 55 m below)
  vec3 p = vec3(position.x, 25.0, position.z) + uWind * s;
  p -= uWind * aEnd * aSpeed * 0.09;                                 // the tail of the streak
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  vA = (1.0 - aEnd * 0.9) * clamp(1.5 - (-mv.z) / 25.0, 0.12, 1.0);
  gl_Position = projectionMatrix * mv;
}
